        var rec = new GroomingRecord { GroomingRecordId = "rec_r1", AppointmentId = appt.AppointmentId, ServiceDate = appt.Date, ServiceTime = appt.Time };
        return new ContractRenderData(owner, pet, appt, rec, Array.Empty<byte>(),
