    // ===== Scenario: OwnerService 對三欄全空之 Owner 寫入不應拋例外 =====
    [Fact(DisplayName = "R1 / OwnerService 對三欄全空之 Owner 寫入不應拋例外")]
    public async Task OwnerService_SaveAsync_with_three_emergency_fields_empty_does_not_throw()
    {
        var (db, conn) = CreateDb();
        using var _ = conn;
        await using var _db = db;
        var ids = new SequentialIdGenerator();
        var clock = new FakeClock();
        var svc = new OwnerService(db, ids, clock);

        // Given EmergencyContact 三欄皆為空字串
        var input = new OwnerInput
        {
            Name = "王小明",
            NationalId = "A123456789",
            Phone = "0912345678",
            Address = "桃園市桃園區慈文路322巷5號",
            EmergencyContactName = "",
            EmergencyContactPhone = "",
            EmergencyContactRelationship = "",
        };

        // When
        var owner = await svc.CreateAsync(input);

        // Then 不應拋例外，且三欄皆為空字串
        owner.OwnerId.Should().StartWith("owner_");
        owner.EmergencyContactName.Should().Be("");
        owner.EmergencyContactPhone.Should().Be("");
        owner.EmergencyContactRelationship.Should().Be("");

        // And SQLite 中確實存在
        var loaded = await svc.GetByIdAsync(owner.OwnerId);
        loaded.EmergencyContactName.Should().Be("");
        loaded.EmergencyContactPhone.Should().Be("");
        loaded.EmergencyContactRelationship.Should().Be("");
    }

