    // ===== Scenario: ContractTemplateRenderer 對三欄全空之 Owner 渲染後 HTML 不應包含 null / 未填寫 / "-" =====
    [Fact(DisplayName = "R1 / Renderer 對三欄全空之 Owner 渲染後 HTML 不應包含佔位字串")]
    public void Renderer_does_not_output_placeholder_for_empty_emergency_fields()
    {
        // Given Owner.EmergencyContactName = "" 且其餘兩欄也為空
        var data = SampleData(emergencyName: "", emergencyPhone: "", emergencyRelationship: "");
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);

        // When 呼叫 Render(data)
        var html = renderer.Render(data);

        // Then HTML 不應出現 "null"、"未填寫"、樣板殘留 "{{owner.emergencyContactName}}"
        html.Should().NotContain("null");
        html.Should().NotContain("未填寫");
        html.Should().NotContain("{{owner.emergencyContactName}}");

        // 緊急聯絡人 <td class="val"> 中三欄皆為空白（不含多餘字符）
        // page1 的緊急聯絡人儲存格（<td class="val" colspan="5">{{owner.emergencyContactName}}</td>）應為空
        html.Should().MatchRegex(@"<td class=""label"">緊急聯絡人</td>\s*<td class=""val"" colspan=""5""></td>");
    }

