    public void Renderer_new_page1_service_record_shows_blank_for_empty_emergency_fields()
    {
        // Given Owner 三欄皆空
        var data = SampleData(emergencyName: "", emergencyPhone: "", emergencyRelationship: "");
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);

        // When
