        // Then 整個 HTML 不應出現 "null" 或 "未填寫"
        html.Should().NotContain("null");
        html.Should().NotContain("未填寫");

        // page2 的 (二) 消費者/飼主 section 中 emergencyContactName 儲存格應為空白
        // 該 section 的 "緊急聯絡人" td 後緊接的 td 應不含實際文字
        var page2Start = html.IndexOf("(二) 消費者/飼主", StringComparison.Ordinal);
