    // ===== Scenario: PuppeteerSharpContractGenerator 對三欄空之 Owner 應產生有效 PDF =====
    [Fact(DisplayName = "R1 / PuppeteerSharp 對三欄空之 Owner 應產出有效 PDF")]
    [Trait("category", "integration")]
    public async Task PuppeteerSharp_generates_valid_pdf_for_owner_with_empty_emergency_fields()
    {
        var data = SampleData(emergencyName: "", emergencyPhone: "", emergencyRelationship: "");
        var cacheDir = Path.Combine(Path.GetTempPath(), "petsalon-test-chromium-cache");

        // When
        await using var gen = new PuppeteerSharpContractGenerator(_templatePath, _fontPath, cacheDir);
        var output = await gen.GenerateContractAsync(data, _tempDir, nextVersion: 1);

        // Then
        File.Exists(output.AbsolutePath).Should().BeTrue();
        var bytes = await File.ReadAllBytesAsync(output.AbsolutePath);
        bytes.Length.Should().BeGreaterThan(5000);
        bytes[0].Should().Be(0x25); bytes[1].Should().Be(0x50);
        bytes[2].Should().Be(0x44); bytes[3].Should().Be(0x46);
    }

    // ===== Scenario Outline: 不同欄位填寫組合下 Renderer 之 HTML 輸出 =====
    [Theory(DisplayName = "R1 / 不同欄位填寫組合下 Renderer 之 HTML 輸出")]
    [InlineData("", "", "", "", "", "")]
