    public void Renderer_emergency_fields_combinations(
        string name, string relationship, string phone,
        string expectedName, string expectedRelationship, string expectedPhone)
    {
        // Given Owner 之三欄為對應 InlineData
        var data = SampleData(emergencyName: name, emergencyPhone: phone, emergencyRelationship: relationship);
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);

        // When
        var html = renderer.Render(data);

        // Then
        // page1 的緊急聯絡人表格
        if (!string.IsNullOrEmpty(expectedName))
            html.Should().Contain(expectedName);
        if (!string.IsNullOrEmpty(expectedRelationship))
            html.Should().Contain(expectedRelationship);
        if (!string.IsNullOrEmpty(expectedPhone))
            html.Should().Contain(expectedPhone);

        // 空值時不應顯示 null
        html.Should().NotContain("null");
        html.Should().NotContain("undefined");
        // 有 relationship 時 page2 應含括號格式，空時不應含 "()"
        if (string.IsNullOrEmpty(relationship))
            html.Should().NotContain("()");
